    {
      "target_id": "t1",
      "policy_source_id": "q13",
      "policy_quote": "After user confirmation, the order status will be changed to 'exchange requested' (or in this case, 'pending (items modified)'), and the user will receive relevant updates (e.g., refund instructions).",
      "requirement": "The assistant must ensure the tool call reflects the correct status transition (e.g., 'pending (items modified)') and that the user is informed of any refunds or updates."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must ensure all values in the tool call (e.g., `order_id`, `item_ids`, `new_item_ids`, `payment_method_id`) are accurate and directly sourced from verified data or user confirmation."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You can only help one user per conversation (but you can handle multiple requests from the same user), and must deny any requests for tasks related to any other user.",
      "requirement": "The assistant must ensure the `order_id` and `payment_method_id` belong to the authenticated user and no other user’s data is processed."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time.",
      "requirement": "The assistant must not send a message to the user while the `modify_pending_order_items` tool call is in progress."
    }
  ]
